// Application registry for the pilot.
// Replace the Slack user IDs with each app's real owner and secondary admin.
// In production, move this to n8n Data Tables or the ServiceNow CMDB.
const registry = [
  {
    vendor_id: 'slack',
    application_name: 'Slack',
    business_criticality: 'critical',
    source_type: 'slack_status_api',
    status_source_url: 'https://slack-status.com/api/v2.0.0/current',
    status_page_url: 'https://slack-status.com/',
    primary_slack_user_id: 'U00000SLACK1',
    secondary_slack_user_id: 'U00000SLACK2',
    enabled: true,
  },
  {
    vendor_id: 'okta',
    application_name: 'Okta',
    business_criticality: 'critical',
    source_type: 'okta_atom',
    status_source_url: 'https://status.okta.com/services/xml/OktaTrustRSS',
    status_page_url: 'https://status.okta.com/',
    primary_slack_user_id: 'U00000OKTA01',
    secondary_slack_user_id: 'U00000OKTA02',
    enabled: true,
  },
  {
    vendor_id: 'google_workspace',
    application_name: 'Google Workspace',
    business_criticality: 'critical',
    source_type: 'google_workspace_json',
    status_source_url: 'https://www.google.com/appsstatus/dashboard/incidents.json',
    status_page_url: 'https://www.google.com/appsstatus/dashboard/',
    primary_slack_user_id: 'U00000GWS001',
    secondary_slack_user_id: 'U00000GWS002',
    enabled: true,
  },
  {
    // Any Atlassian Statuspage-hosted vendor works with source_type "statuspage".
    // Confirm the vendor's /api/v2/incidents.json endpoint, then enable.
    vendor_id: 'atlassian',
    application_name: 'Jira / Confluence',
    business_criticality: 'high',
    source_type: 'statuspage',
    status_source_url: 'https://status.atlassian.com/api/v2/incidents.json',
    status_page_url: 'https://status.atlassian.com/',
    primary_slack_user_id: 'U00000ATL001',
    secondary_slack_user_id: 'U00000ATL002',
    enabled: false,
  },
];

return registry.filter((app) => app.enabled).map((app) => ({ json: app }));

// Normalize each vendor's status data, compare it with stored state, and emit
// only new or materially changed events. State is kept in workflow static data,
// which n8n persists between production (active) executions.
const MAX_TEXT = 280;
const STALE_AFTER_MS = 7 * 24 * 60 * 60 * 1000; // ignore unseen incidents older than this
const PRUNE_AFTER_MS = 30 * 24 * 60 * 60 * 1000; // forget closed incidents after this
const FEED_FAILURES_BEFORE_ALERT = 2;
const FEED_ALERT_COOLDOWN_MS = 60 * 60 * 1000;
const IMPACT_RANK = { critical: 3, major: 2, minor: 1 };
const CLOSED = ['resolved', 'no_longer_listed'];

const state = $getWorkflowStaticData('global');
state.incidents = state.incidents || {};
state.vendors = state.vendors || {};
const now = Date.now();
const nowIso = new Date(now).toISOString();

// ---------- Vendor text is untrusted input ----------
function decodeEntities(s) {
  return s
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&');
}
function clean(text, max = MAX_TEXT) {
  const plain = decodeEntities(String(text ?? '').replace(/<!\[CDATA\[|\]\]>/g, ''))
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const cut = plain.length > max ? `${plain.slice(0, max - 1)}…` : plain;
  // Escape Slack control characters so feed text can't create mentions (<!channel>) or links.
  return cut.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
// Only link to the vendor's own status host; anything else falls back to the status page.
function safeUrl(url, app) {
  try {
    const base = new URL(app.status_page_url);
    const u = new URL(String(url ?? ''), base);
    return u.protocol === 'https:' && u.hostname === base.hostname ? u.toString() : app.status_page_url;
  } catch {
    return app.status_page_url;
  }
}

// ---------- Source adapters: vendor format -> common incident shape ----------
const adapters = {
  // Lists active incidents only, so a missing incident means "no longer listed".
  slack_status_api(raw) {
    const data = JSON.parse(raw);
    return {
      complete: false,
      incidents: (data.active_incidents || []).map((i) => {
        const notes = [...(i.notes || [])].sort((a, b) => String(a.date_created).localeCompare(String(b.date_created)));
        return {
          id: String(i.id),
          title: i.title,
          status: ['resolved', 'completed'].includes(i.status) ? 'resolved' : i.status || 'active',
          impact: i.type === 'outage' ? 'major' : i.type === 'incident' ? 'minor' : 'none',
          components: i.services || [],
          url: i.url,
          updated_at: i.date_updated,
          summary: notes.length ? notes[notes.length - 1].body : '',
        };
      }),
    };
  },
  okta_atom(raw) {
    const tag = (entry, name) => (entry.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)</${name}>`, 'i')) || [])[1] || '';
    const entries = raw.split(/<entry[\s>]/i).slice(1).map((e) => e.split(/<\/entry>/i)[0]);
    return {
      complete: true,
      incidents: entries
        .map((e) => {
          const title = decodeEntities(tag(e, 'title').replace(/<!\[CDATA\[|\]\]>/g, '')).trim();
          const link = (e.match(/<link[^>]*href="([^"]+)"/i) || [])[1] || '';
          const id = (link.match(/#incident\/([A-Za-z0-9]+)/) || [])[1] || tag(e, 'id').trim();
          const t = title.toLowerCase();
          return {
            id,
            title,
            status: t.startsWith('resolved') ? 'resolved' : 'active',
            impact: /outage|disruption/.test(t) ? 'major' : /degradation/.test(t) ? 'minor' : /maintenance/.test(t) ? 'maintenance' : 'unknown',
            components: [],
            url: link,
            updated_at: tag(e, 'updated').trim(),
            summary: tag(e, 'summary') || tag(e, 'content'),
          };
        })
        .filter((i) => i.id),
    };
  },
  google_workspace_json(raw) {
    const list = JSON.parse(raw);
    return {
      complete: true,
      incidents: list.map((i) => {
        const impact = String(i.status_impact || '').toUpperCase();
        const latest = String(i.most_recent_update?.status || '').toUpperCase();
        return {
          id: String(i.id),
          title: i.external_desc,
          status: i.end || latest === 'AVAILABLE' ? 'resolved' : 'active',
          impact: impact === 'SERVICE_OUTAGE' ? 'major' : impact === 'SERVICE_DISRUPTION' ? 'minor' : 'none',
          components: (i.affected_products || []).map((p) => p.title || p.id),
          url: i.uri,
          updated_at: i.modified,
          summary: i.most_recent_update?.text || '',
        };
      }),
    };
  },
  // Atlassian Statuspage public API (/api/v2/incidents.json).
  statuspage(raw) {
    const data = JSON.parse(raw);
    return {
      complete: true,
      incidents: (data.incidents || []).map((i) => ({
        id: String(i.id),
        title: i.name,
        status: ['resolved', 'postmortem', 'completed'].includes(i.status) ? 'resolved' : i.status,
        impact: ['critical', 'major', 'minor', 'maintenance'].includes(i.impact) ? i.impact : 'none',
        components: (i.components || []).map((c) => c.name),
        url: i.shortlink,
        updated_at: i.updated_at,
        summary: i.incident_updates?.[0]?.body || '',
      })),
    };
  },
};

// ---------- Event building ----------
const LABELS = {
  new: { emoji: '🚨', text: 'New vendor incident' },
  updated: { emoji: '🔄', text: 'Vendor update' },
  vendor_resolved: { emoji: '✅', text: 'Vendor reports resolved: verify internal recovery' },
  no_longer_listed: { emoji: '❔', text: 'No longer listed by vendor: verify before closing' },
};

function makeEvent(app, inc, key, changeType, notifyOwners) {
  const label = LABELS[changeType];
  const title = clean(inc.title, 160);
  const components = inc.components.length ? clean(inc.components.join(', '), 160) : 'not specified';
  const url = safeUrl(inc.url, app);
  const priority = notifyOwners ? 'triage_required' : 'informational';
  const lines = [
    `${label.emoji} *${clean(app.application_name)}: ${label.text}*`,
    `*${title}*`,
    `Vendor status: ${clean(inc.status)} · Vendor impact: ${clean(inc.impact)}`,
    `Components: ${components}`,
    'Internal impact: not yet confirmed',
    `<${url}|Vendor source>`,
  ];
  const summary = clean(inc.summary);
  if (summary) lines.splice(4, 0, `Latest vendor note: ${summary}`);
  return {
    event_type: 'incident',
    change_type: changeType,
    incident_key: key,
    vendor_id: app.vendor_id,
    vendor_incident_id: inc.id,
    application_name: app.application_name,
    title,
    vendor_status: inc.status,
    vendor_impact: inc.impact,
    affected_components: inc.components,
    source_url: url,
    internal_impact: 'unconfirmed',
    internal_priority: priority,
    notify_owners: notifyOwners,
    primary_slack_user_id: app.primary_slack_user_id,
    secondary_slack_user_id: app.secondary_slack_user_id,
    channel_text: lines.join('\n'),
    dm_text: [
      `${label.emoji} *SaaS vendor incident: action required*`,
      `Application: ${clean(app.application_name)}`,
      `Issue: ${title}`,
      `Vendor-reported impact: ${clean(inc.impact)} · Status: ${clean(inc.status)}`,
      'Internal impact: not yet confirmed',
      changeType === 'vendor_resolved' || changeType === 'no_longer_listed'
        ? 'Action: confirm our users have recovered before the internal incident is closed.'
        : 'Action: verify impact on our tenant and acknowledge in #saas-alerts.',
      `<${url}|Vendor source>`,
    ].join('\n'),
    detected_at: nowIso,
  };
}

function feedErrorEvent(app, message, failures) {
  return {
    event_type: 'feed_error',
    change_type: 'feed_error',
    vendor_id: app.vendor_id,
    application_name: app.application_name,
    notify_owners: false,
    channel_text: [
      `⚠️ *${clean(app.application_name)}: status feed failing*`,
      `${failures} consecutive polls failed. Vendor incidents may be missed until this is fixed.`,
      `Error: ${clean(message, 200)}`,
      `<${app.status_page_url}|Check the status page manually>`,
    ].join('\n'),
    detected_at: nowIso,
  };
}

// ---------- Main loop ----------
const registry = $('Load Application Registry').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json);
const events = [];

registry.forEach((app, idx) => {
  const res = responses[idx] || {};
  const vendor = (state.vendors[app.vendor_id] = state.vendors[app.vendor_id] || { consecutive_failures: 0 });

  let parsed;
  try {
    if (res.error) throw new Error(typeof res.error === 'string' ? res.error : res.error.message || 'request failed');
    const adapter = adapters[app.source_type];
    if (!adapter) throw new Error(`unknown source_type "${app.source_type}"`);
    parsed = adapter(typeof res.data === 'string' ? res.data : JSON.stringify(res.data ?? res));
  } catch (err) {
    vendor.consecutive_failures += 1;
    const lastAlert = vendor.last_error_alert ? Date.parse(vendor.last_error_alert) : 0;
    if (vendor.consecutive_failures >= FEED_FAILURES_BEFORE_ALERT && now - lastAlert >= FEED_ALERT_COOLDOWN_MS) {
      vendor.last_error_alert = nowIso;
      events.push(feedErrorEvent(app, err.message, vendor.consecutive_failures));
    }
    return;
  }
  vendor.consecutive_failures = 0;
  vendor.last_successful_poll = nowIso;

  // A feed can repeat an incident; keep its most recent entry.
  const latest = {};
  for (const inc of parsed.incidents) {
    const prev = latest[inc.id];
    if (!prev || String(inc.updated_at) > String(prev.updated_at)) latest[inc.id] = inc;
  }

  const seen = new Set();
  for (const inc of Object.values(latest)) {
    const key = `${app.vendor_id}:${inc.id}`;
    seen.add(key);
    const signature = [inc.status, inc.impact, [...inc.components].sort().join(',')].join('|');
    const rec = state.incidents[key];

    if (!rec) {
      const updated = Date.parse(inc.updated_at);
      const stale = Number.isFinite(updated) && now - updated > STALE_AFTER_MS;
      if (inc.status === 'resolved' || stale) continue; // history, not news
      const severe = (IMPACT_RANK[inc.impact] || 0) >= 2;
      const notify = severe && ['critical', 'high'].includes(app.business_criticality);
      state.incidents[key] = { vendor_id: app.vendor_id, status: inc.status, signature, first_seen: nowIso, last_change: nowIso, owners_notified: notify, snapshot: inc };
      events.push(makeEvent(app, inc, key, 'new', notify));
    } else if (rec.signature !== signature) {
      const changeType = inc.status === 'resolved' ? 'vendor_resolved' : 'updated';
      const severe = (IMPACT_RANK[inc.impact] || 0) >= 2;
      const notify = rec.owners_notified || (severe && ['critical', 'high'].includes(app.business_criticality));
      Object.assign(rec, { status: inc.status, signature, last_change: nowIso, owners_notified: notify, snapshot: inc });
      events.push(makeEvent(app, inc, key, changeType, notify));
    }
  }

  // Feeds that list only active incidents: flag disappearances, never auto-resolve.
  if (!parsed.complete) {
    for (const [key, rec] of Object.entries(state.incidents)) {
      if (rec.vendor_id !== app.vendor_id || seen.has(key) || CLOSED.includes(rec.status)) continue;
      Object.assign(rec, { status: 'no_longer_listed', signature: 'no_longer_listed', last_change: nowIso });
      events.push(makeEvent(app, { ...rec.snapshot, status: 'no_longer_listed' }, key, 'no_longer_listed', rec.owners_notified));
    }
  }
});

for (const [key, rec] of Object.entries(state.incidents)) {
  if (CLOSED.includes(rec.status) && now - Date.parse(rec.last_change) > PRUNE_AFTER_MS) delete state.incidents[key];
}

return events.map((json) => ({ json }));

// One Slack DM per owner for events that need owner action.
const out = [];
for (const { json: e } of $input.all()) {
  if (!e.notify_owners) continue;
  const recipients = new Set([e.primary_slack_user_id, e.secondary_slack_user_id].filter(Boolean));
  for (const id of recipients) out.push({ json: { slack_user_id: id, text: e.dm_text, incident_key: e.incident_key } });
}
return out;
